package com.franco.desco.application.visit.service;import com.franco.desco.application.visit.*;import com.franco.desco.application.visit.port.in.VisitUseCase;import com.franco.desco.application.visit.port.out.VisitPersistencePort;import com.franco.desco.application.shared.*;import com.franco.desco.application.shared.pagination.PageResult;import com.franco.desco.domain.visit.VisitModels;
public final class VisitApplicationService implements VisitUseCase{private final VisitPersistencePort p;public VisitApplicationService(VisitPersistencePort p){this.p=p;}public AppResult<PageResult<VisitModels.Summary>>list(VisitCommands.ListVisits c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.list(c,i,m),"VISITAS_LISTADAS","VISITAS_NO_LISTADAS",AppStatus.BAD_REQUEST);}public AppResult<VisitModels.Detail>get(VisitCommands.Get c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.get(c,i,m),"VISITA_CONSULTADA","VISITA_NO_DISPONIBLE",AppStatus.BAD_REQUEST);}public AppResult<Long>start(VisitCommands.Start c,SessionIdentity i,RequestMetadata m){return ApplicationResults.created(p.start(c,i,m),"VISITA_INICIADA","VISITA_NO_INICIADA");}public AppResult<Void>update(VisitCommands.Update c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.update(c,i,m),"VISITA_ACTUALIZADA","VISITA_NO_ACTUALIZADA",AppStatus.BAD_REQUEST);}public AppResult<Void>finish(VisitCommands.Finish c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.finish(c,i,m),"VISITA_FINALIZADA","VISITA_NO_FINALIZADA",AppStatus.BAD_REQUEST);}public AppResult<Void>annul(VisitCommands.Annul c,SessionIdentity i,RequestMetadata m){return ApplicationResults.ok(p.annul(c,i,m),"VISITA_ANULADA","VISITA_NO_ANULADA",AppStatus.BAD_REQUEST);}}
